    def mru_callable(cache):
        def _mru_get(k):
            try:
                return cache[k]
            except KeyError:
                pass # key not found
            cache[k] = []
            return cache[k]
        def _mru_evict(k, value):
            try:
                del cache[k]
            except KeyError:
                pass # key not found
            cache[k] = value
        return _mru_get, _mru_evict
