def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for arg in args:
        if isinstance(arg, Or) and isinstance(arg.args[0], And):
            # Absorption
            if arg.args[0].args[0] == arg.args[1]:
                new_args.append(arg.args[0].args[0])
            else:
                new_args.append(And(arg.args[0].args[0], arg.args[1]))
        elif isinstance(arg, And) and isinstance(arg.args[0], Not) and isinstance(arg.args[1], Or):
            # Negative absorption
            if arg.args[0].args[0] == arg.args[1].args[1]:
                new_args.append(And(arg.args[0].args[0], arg.args[1].args[0]))
            elif arg.args[0].args[0] == arg.args[1].args[0]:
                new_args.append(Or(arg.args[0].args[0], arg.args[1].args[1]))
            else:
                new_args.append(arg)
        else:
            new_args.append(arg)
    return new_args

def _fromutc(self, dt):
    """
    Given a timezone-aware datetime in a given timezone, calculates a
    timezone-aware datetime in a new timezone.

    Since this is the one time that we *know* we have an unambiguous
    datetime object, we take this opportunity to determine whether the
    datetime is ambiguous and in a "fold" state (e.g. if it's the first
    occurrence, chronologically, of the ambiguous datetime).

    :param dt:
        A timezone-aware :class:`datetime.datetime` object.
    """
    if not dt.tzinfo:
        return dt
    if hasattr(dt, "astimezone"):
        return dt.astimezone(self.tzinfo)
    else:
        return dt.replace(tzinfo=self.tzinfo)

