            raise ValueError("Signed element is not signed with the expected public key")
        verify_signature(signed_element, signature)
        return True

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    try:
        return json.loads(document)
    except json.JSONDecodeError:
        xrd = parse_xrds(document)
        result = {"alias": xrd["alias"]}
        for link in xrd["links"]:
            if link["rel"] == "http://diaspora.io/ns/diaspora":
                result["diaspora_url"] = link["template"]
            elif link["rel"] == "lrdd":
                result["lrdd_url"] = link["template"]
            elif link["rel"] == "lrdd":
                result["hcard_url"] = link["template"]
            elif link["rel"] == "diaspora/app":
                result["app_URL"] = link["template"]
        return result

