def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args = self.parsed_yaml.get('deprecated-args', {})
    if not deprecated_args:
        # No deprecated args, nothing to do
        return

    cli_args = cli_args or {}
    answer_file_args = answer_file_args or {}
    cli_args = _check_args(self, cli_args)
    answer_file_args = _check_args(self, answer_file_args)

    for deprecated_arg, current_arg in deprecated_args.items():
        if current_arg in cli_args:
            current_arg_val = cli_args[current_arg]
        elif current_arg in answer_file_args:
            current_arg_val = answer_file_args[current_arg]
        else:
            # This should never happen. If the deprecated arg is missing from
            # both the cli and answer file, there's nothing for us to do.
            continue

        if current_arg_val == 'None':
            current_arg_val = '""'

        # We've got the deprecated arg and its value, let's print a warning
        print(
            f"The argument '{deprecated_arg}' has been deprecated in favor of "
            f"'{current_arg}'. Please update your usage accordingly."
        )

        # It'd be nice if we could print a stacktrace here, but that's a bit too
        # complicated. Just setting the warning category to RuntimeWarning for
        # now.
        warnings.warn(
            f"Argument '{deprecated_arg}' has been deprecated",
            category=RuntimeWarning,
        )

def validate_length_args(self, args):
    """
    Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    for arg, length in args.items():
        if length is not None and len(arg) > length:
            raise ValueError(f"Argument {arg} is too long (maximum length: {length})")

def validate_min_max_args(self, args):
    for arg in args:
        arg_value = arg
        # check if minimum value is specified
        if 'min' in arg.ncattrs():
            min_val = arg.min
            # check if argument value is less than minimum value
            if arg_value < min_val:
                raise ValueError(f"{arg.name} value of {arg_value} is less than minimum value of {min_val}")
        # check if maximum value is specified
        if 'max'in arg.ncattrs():
            max_val = arg.max
            # check if argument value is greater than maximum value
            if arg_value > max_val:
                raise ValueError(f"{arg.name} value of {arg_value} is greater than maximum value of {max_val}")
    return args

