def _convert_non_cli_args(parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # define the type converters for each parameter
    converters = {
        "hello_dir": str,
        "random_positive_int": int,
        "reverse_string": str,
        "uppercase_string": str
    }

    # iterate over the arguments
    for arg_name in values_dict:
        # check if the argument is a recognized parameter
        if arg_name in converters:
            # convert the argument to the correct type
            values_dict[arg_name] = converters[arg_name](values_dict[arg_name])

        elif arg_name == "repeat_count":
            values_dict["repeat_count"] = int(values_dict[arg_name])

        elif arg_name == "head_name":
            values_dict["head_name"] = str(values_dict[arg_name])

        elif arg_name == "tail_name":
            values_dict["tail_name"] = str(values_dict[arg_name])

        else:
            # unknown argument, skip it
            pass

